head.script:
// Resize iframes on articles with interactives when they send a RESIZE message
window.addEventListener('message', (event) => {
  if (event.data.type === 'RESIZE') {
    const height = parseInt(event.data.payload.height, 10);
    Array.prototype.forEach.call(document.getElementsByTagName('iframe'), function (element) {
      if (element.contentWindow === event.source) {
        element.style.height = height + 'px';
      }
    });
  }
}, false);

window.experimentIntegration = {
   getUser: () => {
     return {
       user_id: 'e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855',
       device_id: 'undefined'
     };
   },
   track: (e) => {
     window.tedl = window.tedl || {};
     window.tedl.events = window.tedl.events || [];
     window.tedl.events.push({
       name: e.eventType,
       properties: e.eventProperties,
       user_id: 'e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855',
       device_id: 'undefined',
     });
     return true;
   },
 };

